// Кейс: .qa/tests/admin/AD-12-section-position-order-delete.md.
import { $$, expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText, pageCounter } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { openAdminPrayer, setField, saveDraft, approveDraft, qaMarker, historyEntry } from '../_lib/admin.ts';
import { goHome, openProfile, waitHuman, openCatalogPrayer, goPage, nodes, button, saveArtifact } from '../_lib/readiness-1910.ts';
import {
  dismissCrashAlert, approvedCount, sectionRows, buttonContaining, countButtonsContaining,
  ADM_ADD_START, ADM_ADD_HERE, ADM_ADD_END, ADM_DOWN, ADM_NEW_TITLE, ADM_BANNER_START, ADM_BANNER_END_OLD,
  ADM_DELETE, ADM_DELETE_TITLE, ADM_DELETE_BODY, ADM_MOVE_PENDING, ADM_APPROVE_CHANGE, ADM_POS_SECTION, saveShot,
} from '../_lib/app-2110.ts';

const PRAYER = 'ברכת הלבנה';
const NUSACH = 'אשכנז';
const APPROVER = process.env.QA_APPROVER || 'בודק QA';
const QA_TITLE = `QA-AUTO בדיקת מיקום ${new Date().getDate()}.${new Date().getMonth() + 1}`;
const QA_BODY = 'בדיקת QA — קטע בדיקה זמני, יימחק';

type El = WebdriverIO.Element;

async function adminEntryVisible() {
  try { await openProfile(); await scrollToText('ממשק ניהול התוכן', 6); return true; } catch { return false; }
}
const openAdmin = () => openAdminPrayer(PRAYER, NUSACH);
const hasQaRow = (rows: string[]) => rows.some((r) => r.includes(QA_TITLE));

/** Открыть QA קטע из списка админки (строка «N, QA-AUTO …, <статус>»). */
async function openQaSection() {
  await openAdmin();
  const row = await byTextContains(QA_TITLE);
  await scrollToText(QA_TITLE, 15);
  await row.click();
  await (await byText('עריכת קטע')).waitForExist({ timeout: 20000 });
}
/** Утвердить структурное изменение (перемещение/удаление) кнопкой «אישור ופרסום השינוי» — только своё изменение. */
async function approveChange(marker: string) {
  await setField('שם המאשר', APPROVER);
  await setField('הערה לאישור (לא חובה)', marker);
  await (await scrollToText(ADM_APPROVE_CHANGE)).click();
  // Окно-подтверждение публикации (если есть) — «אישור».
  const ok = await button('אישור');
  if (await ok.waitForExist({ timeout: 8000 }).then(() => true, () => false)) await ok.click();
  await driver.waitUntil(async () => !(await shown(byText(ADM_APPROVE_CHANGE))), { timeout: 30000, timeoutMsg: '«אישור ופרסום השינוי» не применилось' });
}
/** Кнопка «מחיקת הקטע» внутри окна (а не та, что в карточке «מיקום ומחיקה» под окном): ближайшая ниже заголовка окна. */
async function dialogDeleteButton(): Promise<El> {
  const title = (await nodes()).find((n) => n.label.startsWith('למחוק את הקטע'));
  if (!title) throw new Error('нет окна «למחוק את הקטע …?»');
  const els = await $$(driver.isAndroid
    ? `android=new UiSelector().text("${ADM_DELETE}")`
    : `-ios predicate string:type == "XCUIElementTypeButton" AND (name == "${ADM_DELETE}" OR label == "${ADM_DELETE}")`).getElements();
  let best: El | null = null; let bestDy = Infinity;
  for (const e of els) {
    const { y } = await e.getLocation();
    const dy = y - title.y;
    if (dy > 0 && dy < 500 && dy < bestDy) { bestDy = dy; best = e as unknown as El; }
  }
  if (!best) throw new Error('кнопка «מחיקת הקטע» окна не найдена');
  return best;
}
/** Удалить QA קטע: «מחיקת הקטע» → окно → (cancelFirst: «ביטול» — ничего не удалено) → «מחיקת הקטע» в окне → утвердить. */
async function deleteQaSection(marker: string, cancelFirst: boolean) {
  await openQaSection();
  if (cancelFirst) {
    await (await scrollToText(ADM_DELETE)).click();
    await expect(byText(ADM_DELETE_TITLE(QA_TITLE))).toBeExisting({ wait: 10000 });
    await expect(byTextContains(ADM_DELETE_BODY)).toBeExisting();
    await (await button('ביטול')).click();
    await expect(byText(ADM_DELETE_TITLE(QA_TITLE))).not.toBeExisting({ wait: 10000 });
    await expect(byText('עריכת קטע')).toBeExisting();
  }
  await (await scrollToText(ADM_DELETE)).click();
  await (await byText(ADM_DELETE_TITLE(QA_TITLE))).waitForExist({ timeout: 10000 });
  await (await dialogDeleteButton()).click();
  await approveChange(marker);
}

/** Экран пользователя: открыть «ברכת הלבנה» и вернуть [M страниц, все тексты по страницам].
 *  Без обхода #1b6593 (исправлен 25.10): если приложение упало — тест падает с понятной причиной, без перезапуска и перелогина. */
async function userView(): Promise<{ total: number; text: string }> {
  await goHome();
  await openCatalogPrayer(PRAYER).catch(async (e) => {
    if (await dismissCrashAlert()) throw new Error('приложение упало при открытии «תפילות»/молитвы после публикации — регресс #1b6593');
    throw e;
  });
  const total = Number((await pageCounter()).split(' מתוך ')[1]);
  let text = '';
  for (let p = 1; p <= total; p++) {
    await goPage(p);
    text += `\n[стр ${p}]\n` + (await nodes()).map((n) => n.label).join('\n');
  }
  return { total, text };
}

describe('21.10 — админка: место, порядок и удаление קטע (#6bddd9)', () => {
  before(async function () {
    this.timeout(1000000);
    if (process.env.QA_ADMIN_MANUAL !== '1') skipWith(this, 'нужен вход клиента (админ) человеком — запуск с QA_ADMIN_MANUAL=1');
    if (!(await adminEntryVisible())) await waitHuman('войдите в приложение аккаунтом КЛИЕНТА (в профиле должен быть «ממשק ניהול התוכן»)', adminEntryVisible);
  });
  after(async () => { await goHome().catch(() => {}); });

  it('AD-12a Список קטעים: «+ הוספת קטע בתחילת התפילה», «+ הוספת קטע כאן» после каждого קטע, «הוספת קטע» в конце; в «עריכת קטע» — карточка «מיקום ומחיקה» с «מחיקת הקטע» (только просмотр) #6bddd9 #16933ca6 @admin @prod-safe', async () => {
    await openAdmin();
    const [, m] = await approvedCount();
    expect(await (await buttonContaining(ADM_ADD_START)).isExisting()).toBe(true);
    await scrollToText('קטעי התפילה');
    const rows = await sectionRows();
    console.log(`[AD-12a] ${PRAYER} ${NUSACH}: ${m} קטעים, строки: ${rows.join(' | ')}`);
    expect(rows.length).toBe(m);
    expect(await countButtonsContaining(ADM_ADD_HERE)).toBe(m);
    expect(await (await button(ADM_ADD_END)).isExisting()).toBe(true);
    await (await byTextContains(rows[0].split(', ')[1])).click();
    await (await byText('עריכת קטע')).waitForExist({ timeout: 20000 });
    await scrollToText(ADM_POS_SECTION);
    await expect(byText(ADM_DELETE)).toBeExisting();
  });

  it('AD-12b QA קטע в начало → черновик не виден пользователю → «אישור ופרסום» → у пользователя первым, M+1; «↓ למטה» → «הקטע מסומן להעברה…», у пользователя прежний порядок до «אישור ופרסום השינוי», после — вторым; «מחיקת הקטע»: окно, «ביטול» ничего не удаляет, удаление + утверждение → у пользователя исчез; история; всё как было #6bddd9 #16933ca6 F-102 AC1 AC4 AC5 @admin @data @manual-check', async function () {
    this.timeout(3600000);
    // 0. Исходное состояние (снимок в файл).
    await openAdmin();
    const [n0, m0] = await approvedCount();
    await scrollToText('קטעי התפילה');
    const orig = await sectionRows();
    if (hasQaRow(orig)) throw new Error(`в «${PRAYER}» уже есть «${QA_TITLE}» — убрать вручную перед тестом`);
    const user0 = await userView();
    const snap = saveArtifact(`AD-12-orig-${Date.now()}.json`, { n0, m0, orig, userTotal: user0.total });
    console.log(`[AD-12b] исходно: ${n0}/${m0}, ${orig.join(' | ')}; у пользователя ${user0.total} стр.; снимок ${snap}`);
    const marks = { add: qaMarker('AD12-add'), move: qaMarker('AD12-move'), del: qaMarker('AD12-del') };
    try {
      // 1. Добавить в начало: форма «קטע חדש» говорит «…יתווסף בתחילת התפילה», не «…בסוף התפילה».
      await openAdmin();
      await (await buttonContaining(ADM_ADD_START)).click();
      await (await byText(ADM_NEW_TITLE)).waitForExist({ timeout: 20000 });
      await expect(byTextContains(ADM_BANNER_START)).toBeExisting();
      expect(await shown(byTextContains(ADM_BANNER_END_OLD))).toBe(false);
      await setField('כותרת הקטע', QA_TITLE);       // ввод значением элемента (setValue), не mobile:keys
      await setField('טקסט התפילה', QA_BODY);
      await saveDraft();
      await saveShot('AD-12-draft.png');

      // 2. Черновик не виден пользователю (F-102 AC1).
      let u = await userView();
      expect(u.total).toBe(user0.total);
      expect(u.text).not.toContain(QA_TITLE);

      // 3. Утвердить свой קטע («אישור ופרסום» у קטע, НЕ «אישור כל התפילה») → у пользователя первым, страниц +1.
      await openQaSection();
      await setField('שם המאשר', APPROVER);
      await approveDraft(marks.add);
      await openAdmin();
      let rows = await sectionRows();
      expect(rows[0]).toContain(QA_TITLE);
      expect(rows.length).toBe(m0 + 1);
      u = await userView();
      expect(u.total).toBe(user0.total + 1);
      expect(u.text.split('[стр 2]')[0]).toContain(QA_TITLE);

      // 4. «↓ למטה» у QA קטע → черновик перемещения; у пользователя всё ещё первым.
      await openAdmin();
      await scrollToText(QA_TITLE);
      const down = (await nodes()).find((n) => n.label.includes(ADM_DOWN) && n.label.includes(QA_TITLE));
      await (down ? await byTextContains(down.label) : await buttonContaining(ADM_DOWN)).click();   // первый «↓» — у первого קטע (QA)
      await driver.waitUntil(async () => (await sectionRows())[1]?.includes(QA_TITLE) ?? false,
        { timeout: 15000, timeoutMsg: 'после «↓ למטה» QA קטע не стал вторым в списке' });
      await openQaSection();
      await expect(byTextContains(ADM_MOVE_PENDING)).toBeExisting({ wait: 10000 });
      u = await userView();
      expect(u.text.split('[стр 2]')[0]).toContain(QA_TITLE);
      await openQaSection();
      await approveChange(marks.move);
      u = await userView();
      expect(u.text.split('[стр 2]')[0]).not.toContain(QA_TITLE);
      expect(u.text).toContain(QA_TITLE);

      // 5. Удаление: окно, «ביטול», затем удаление + утверждение → у пользователя нет, страниц как было.
      await deleteQaSection(marks.del, true);
      u = await userView();
      expect(u.text).not.toContain(QA_TITLE);
      expect(u.total).toBe(user0.total);

      // 6. История: три записи с нашими метками (кто/когда/место).
      await openAdmin();
      for (const mk of Object.values(marks)) await historyEntry(mk);
    } finally {
      // Возврат: QA קטע удалён и утверждён; список и счётчик как в снимке.
      await openAdmin();
      if (hasQaRow(await sectionRows())) await deleteQaSection(qaMarker('AD12-restore'), false);
      await openAdmin();
      const rowsNow = await sectionRows();
      const countNow = await approvedCount();
      if (JSON.stringify(rowsNow) !== JSON.stringify(orig) || countNow[0] !== n0 || countNow[1] !== m0) {
        throw new Error(`«${PRAYER}» не вернулась: ${rowsNow.join(' | ')} (${countNow.join('/')}) против ${orig.join(' | ')} (${n0}/${m0}) — см. ${snap}`);
      }
      await expect(byTextMatches(`${n0} מתוך ${m0} קטעים מאושרים`)).toBeExisting();
    }
  });
});
